{"emailHash":"f7a2d767d7675529ad225713fe492486165165f2466a70df0d5f330a02ffa3f9","parentHash":null,"from":"Benjamin Williams KC","to":"Anna Varga; T.Barclay@4newsquare.com","subject":"RE: Re: LD Agency","date":"2025-10-07T13:20:57.000Z","attachments":true,"body":"

